// Una web por ejecución (modo "Run Once for Each Item"). Se mide el
// tiempo de respuesta a mano porque el nodo HTTP Request no lo expone, y
// se captura cualquier fallo de red como "caída" en vez de romper el flujo
// (equivalente a Continue On Fail, pero con control total del resultado).
const site = $input.item.json;
const start = Date.now();

let ok = false;
let statusCode = null;
let responseMs = null;
let error = null;

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: site.url,
    timeout: 10000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  responseMs = Date.now() - start;
  statusCode = response.statusCode;
  ok = statusCode >= 200 && statusCode < 400;
  if (!ok) {
    error = `HTTP ${statusCode}`;
  }
} catch (err) {
  responseMs = Date.now() - start;
  error = (err && err.message) ? err.message.slice(0, 500) : 'Error de red';
}

return {
  json: {
    site_id: site.id,
    ok,
    status_code: statusCode,
    response_ms: responseMs,
    error,
  },
};
